C identical-quark interference, boson on the incoming-quark line in
C both amplitudes (CC: pair flavour = partner of the incoming quark)
      SUBROUTINE FEXX3(k,p1,p2,p3,p4,EXXPV,EXXSY)
      IMPLICIT DOUBLE PRECISION (A-Z)
      INTEGER I
      DIMENSION TMP4(4)
      DIMENSION k(4),p1(4),p2(4),p3(4),p4(4)
C---dot products (metric +,-,-,-), DISENT layout (px,py,pz,E)
      kp1=k(4)*p1(4)-k(1)*p1(1)-k(2)*p1(2)-k(3)*p1(3)
      kp2=k(4)*p2(4)-k(1)*p2(1)-k(2)*p2(2)-k(3)*p2(3)
      kp3=k(4)*p3(4)-k(1)*p3(1)-k(2)*p3(2)-k(3)*p3(3)
      kp4=k(4)*p4(4)-k(1)*p4(1)-k(2)*p4(2)-k(3)*p4(3)
      p1p2=p1(4)*p2(4)-p1(1)*p2(1)-p1(2)*p2(2)-p1(3)*p2(3)
      p1p3=p1(4)*p3(4)-p1(1)*p3(1)-p1(2)*p3(2)-p1(3)*p3(3)
      p1p4=p1(4)*p4(4)-p1(1)*p4(1)-p1(2)*p4(2)-p1(3)*p4(3)
      p2p3=p2(4)*p3(4)-p2(1)*p3(1)-p2(2)*p3(2)-p2(3)*p3(3)
      p2p4=p2(4)*p4(4)-p2(1)*p4(1)-p2(2)*p4(2)-p2(3)*p4(3)
      p3p4=p3(4)*p4(4)-p3(1)*p4(1)-p3(2)*p4(2)-p3(3)*p4(3)
      DO I=1,4
        TMP4(I)=p3(I)+p4(I)
      ENDDO
      Dcd=1/(TMP4(4)**2-TMP4(1)**2-TMP4(2)**2-TMP4(3)**2)
      DO I=1,4
        TMP4(I)=p2(I)+p3(I)+p4(I)
      ENDDO
      Dx1=1/(TMP4(4)**2-TMP4(1)**2-TMP4(2)**2-TMP4(3)**2)
      DO I=1,4
        TMP4(I)=-p1(I)+p3(I)+p4(I)
      ENDDO
      Dx2=1/(TMP4(4)**2-TMP4(1)**2-TMP4(2)**2-TMP4(3)**2)
      DO I=1,4
        TMP4(I)=p3(I)+p2(I)+p4(I)
      ENDDO
      Dcab=1/(TMP4(4)**2-TMP4(1)**2-TMP4(2)**2-TMP4(3)**2)
      DO I=1,4
