C spin-correlated l q(p1) -> l q(p2) g(p3) with the gluon polarisation
C sum replaced by vv vv: helicity difference and sum
      SUBROUTINE FCONTH3(k,p1,p2,p3,vv,C3PV,C3SY)
      IMPLICIT DOUBLE PRECISION (A-Z)
      INTEGER I
      DIMENSION TMP4(4)
      DIMENSION k(4),p1(4),p2(4),p3(4),vv(4)
C---dot products (metric +,-,-,-), DISENT layout (px,py,pz,E)
      kp1=k(4)*p1(4)-k(1)*p1(1)-k(2)*p1(2)-k(3)*p1(3)
      kp2=k(4)*p2(4)-k(1)*p2(1)-k(2)*p2(2)-k(3)*p2(3)
      kp3=k(4)*p3(4)-k(1)*p3(1)-k(2)*p3(2)-k(3)*p3(3)
      kvv=k(4)*vv(4)-k(1)*vv(1)-k(2)*vv(2)-k(3)*vv(3)
      p1p2=p1(4)*p2(4)-p1(1)*p2(1)-p1(2)*p2(2)-p1(3)*p2(3)
      p1p3=p1(4)*p3(4)-p1(1)*p3(1)-p1(2)*p3(2)-p1(3)*p3(3)
      p1vv=p1(4)*vv(4)-p1(1)*vv(1)-p1(2)*vv(2)-p1(3)*vv(3)
      p2p3=p2(4)*p3(4)-p2(1)*p3(1)-p2(2)*p3(2)-p2(3)*p3(3)
      p2vv=p2(4)*vv(4)-p2(1)*vv(1)-p2(2)*vv(2)-p2(3)*vv(3)
      p3vv=p3(4)*vv(4)-p3(1)*vv(1)-p3(2)*vv(2)-p3(3)*vv(3)
      vvvv=vv(4)*vv(4)-vv(1)*vv(1)-vv(2)*vv(2)-vv(3)*vv(3)
      DO I=1,4
        TMP4(I)=p2(I)+p3(I)
      ENDDO
      Dac=1/(TMP4(4)**2-TMP4(1)**2-TMP4(2)**2-TMP4(3)**2)
      DO I=1,4
        TMP4(I)=-p1(I)+p3(I)
      ENDDO
      Dbc=1/(TMP4(4)**2-TMP4(1)**2-TMP4(2)**2-TMP4(3)**2)

      Z1_=kp2 + kp1
      Z2_=Z1_ + kp3
      Z2_=Z2_*p1p2
      Z3_=kp1*p1p3
      Z4_=p2p3*kp1
      Z5_= - Z2_ - Z3_ + 2*Z4_
      Z5_=p3vv*Z5_
      Z6_=p1p3**2
      Z7_=2*p1p3
      Z8_= - p2p3*Z7_
      Z8_=Z6_ + Z8_
